package com.dongqh.luckyhub.order;
import com.dongqh.luckyhub.catalog.enums.ProductType; import com.dongqh.luckyhub.catalog.model.PurchasableSkuSnapshot; import com.dongqh.luckyhub.coupon.model.CouponLockSnapshot; import com.dongqh.luckyhub.membership.model.ActiveMembershipBenefit; import com.dongqh.luckyhub.order.service.OrderPricingService; import org.junit.jupiter.api.Test; import java.time.LocalDateTime; import static org.assertj.core.api.Assertions.*;
class OrderPricingServiceTests { private final OrderPricingService service=new com.dongqh.luckyhub.order.service.impl.OrderPricingServiceImpl();
 @Test void appliesMembershipThenCouponAndFloorsAtZero(){var sku=new PurchasableSkuSnapshot(1L,2L,"P","商品","S","规格",ProductType.PHYSICAL,null,10000L);var member=new ActiveMembershipBenefit("MEMBER",9000,1,10000,LocalDateTime.now().plusDays(1));var quote=service.quote(sku,1,member,new CouponLockSnapshot(3L,4L,"满80减20",2000L));assertThat(quote.originalAmountCent()).isEqualTo(10000L);assertThat(quote.membershipDiscountCent()).isEqualTo(1000L);assertThat(quote.amountAfterMembershipCent()).isEqualTo(9000L);assertThat(quote.couponDiscountCent()).isEqualTo(2000L);assertThat(quote.payableAmountCent()).isEqualTo(7000L);var free=service.quote(sku,1,null,new CouponLockSnapshot(3L,4L,"大额券",20000L));assertThat(free.payableAmountCent()).isZero();}
 @Test void rejectsMultiplicationOverflow(){var sku=new PurchasableSkuSnapshot(1L,2L,"P","商品","S","规格",ProductType.PHYSICAL,null,Long.MAX_VALUE);assertThatThrownBy(()->service.quote(sku,2,null,null)).hasMessageContaining("溢出");}
}
